4	export async function GET() {
5	  const items = await prisma.item.findMany({
6	    include: { category: true },
7	    orderBy: { code: "asc" },
8	  });
9	
10	  const headers = [
11	    "编号", "名称", "描述", "SN号", "型号", "厂商", "分类", "单位",
12	    "库存数量", "安全库存", "存放位置", "供应商", "参考单价",
13	    "维保起始", "维保截止", "SSD颗粒", "适用产品",
14	  ];
15	
16	  const rows = items.map((i) => [
17	    i.code, i.name, i.description ?? "", i.sn ?? "", i.model ?? "",
18	    i.manufacturer ?? "", i.category.name, i.unit,
19	    String(i.quantity), String(i.safetyStock), i.position ?? "",
20	    i.supplier ?? "", i.price != null ? String(i.price) : "",
21	    i.warrantyStart?.toISOString().split("T")[0] ?? "",
22	    i.warrantyEnd?.toISOString().split("T")[0] ?? "",
23	    i.nandType ?? "", i.compatibleProducts ?? "",
24	  ]);
25	
26	  const csvContent = [headers, ...rows]
27	    .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
28	    .join("\n");
29	
30	  // Add BOM for Excel Chinese support
31	  const bom = "﻿";
32	
33	  return new NextResponse(bom + csvContent, {
34	    headers: {
35	      "Content-Type": "text/csv; charset=utf-8",
36	      "Content-Disposition": `attachment; filename="items-${new Date().toISOString().split("T")[0]}.csv"`,
37	    },
38	  });
39	}
