1	import { NextRequest, NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	
4	export async function GET(request: NextRequest) {
5	  const { searchParams } = new URL(request.url);
6	  const type = searchParams.get("type") ?? "";
7	  const itemId = searchParams.get("itemId") ?? "";
8	  const page = parseInt(searchParams.get("page") ?? "1");
9	  const limit = parseInt(searchParams.get("limit") ?? "50");
10	
11	  const where: Record<string, unknown> = {};
12	  if (type) where.type = type;
13	  if (itemId) where.itemId = itemId;
14	
15	  const [transactions, total] = await Promise.all([
16	    prisma.transaction.findMany({
17	      where,
18	      include: { item: { select: { id: true, code: true, name: true, unit: true } } },
19	      orderBy: { createdAt: "desc" },
20	      skip: (page - 1) * limit,
21	      take: limit,
22	    }),
23	    prisma.transaction.count({ where }),
24	  ]);
25	
26	  return NextResponse.json({ transactions, total, page, limit });
27	}
28	
29	export async function POST(request: Request) {
30	  const data = await request.json();
31	
32	  if (!data.type || !["IN", "OUT"].includes(data.type)) {
33	    return NextResponse.json(
34	      { error: "类型必须为 IN 或 OUT" },
35	      { status: 400 }
36	    );
37	  }
38	
39	  if (!data.items || !Array.isArray(data.items) || data.items.length === 0) {
40	    return NextResponse.json(
41	      { error: "至少需要一个物料" },
42	      { status: 400 }
43	    );
44	  }
45	
46	  const batchId = Date.now().toString(36);
47	  const type = data.type;
48	
49	  try {
50	    const results = [];
51	    for (const row of data.items) {
52	      if (!row.itemId || !row.quantity || row.quantity <= 0) {
53	        return NextResponse.json(
54	          { error: "每个物料必须指定 itemId 和有效数量" },
55	          { status: 400 }
56	        );
57	      }
58	
59	      const result = await prisma.$transaction(async (tx) => {
60	        const item = await tx.item.findUnique({ where: { id: row.itemId } });
61	        if (!item) {
62	          throw new Error(`物料 ${row.itemId} 不存在`);
63	        }
64	
65	        const qtyChange = type === "IN" ? row.quantity : -row.quantity;
66	        const newQuantity = item.quantity + qtyChange;
67	
68	        if (type === "OUT" && newQuantity < 0) {
69	          throw new Error(`物料 ${item.name} 库存不足 (当前: ${item.quantity} ${item.unit})`);
70	        }
71	
72	        const [txn] = await Promise.all([
73	          tx.transaction.create({
74	            data: {
75	              type,
76	              itemId: row.itemId,
77	              quantity: row.quantity,
78	              reason: row.reason,
79	              relatedPerson: row.relatedPerson,
80	              note: row.note,
81	              batchId,
82	            },
83	          }),
84	          tx.item.update({
85	            where: { id: row.itemId },
86	            data: { quantity: newQuantity },
87	          }),
88	        ]);
89	        return txn;
90	      });
91	
92	      results.push(result);
93	    }
94	
95	    return NextResponse.json({ batchId, transactions: results }, { status: 201 });
96	  } catch (e) {
97	    const message = e instanceof Error ? e.message : "操作失败";
98	    return NextResponse.json({ error: message }, { status: 400 });
99	  }
100	}
