5	export async function GET() {
6	  const dbPath = path.join(process.cwd(), "prisma", "dev.db");
7	  if (!existsSync(dbPath)) {
8	    return NextResponse.json({ error: "数据库文件不存在" }, { status: 404 });
9	  }
10	
11	  const buffer = readFileSync(dbPath);
12	  const date = new Date().toISOString().split("T")[0];
13	
14	  return new NextResponse(buffer, {
15	    headers: {
16	      "Content-Type": "application/octet-stream",
17	      "Content-Disposition": `attachment; filename="backup-${date}.db"`,
18	    },
19	  });
20	}
