4	export async function GET(request: NextRequest) {
5	  const { searchParams } = new URL(request.url);
6	  const batchId = searchParams.get("batchId") ?? "";
7	
8	  if (batchId) {
9	    const items = await prisma.stockTake.findMany({
10	      where: { batchId },
11	      include: {
12	        item: { select: { id: true, code: true, name: true, unit: true, position: true } },
13	      },
14	      orderBy: { item: { name: "asc" } },
15	    });
16	    return NextResponse.json(items);
17	  }
18	
19	  const batches = await prisma.stockTake.groupBy({
20	    by: ["batchId"],
21	    _count: { id: true },
22	    _min: { createdAt: true },
23	    orderBy: { _min: { createdAt: "desc" } },
24	  });
25	  return NextResponse.json(batches);
26	}
