63	export async function DELETE(
64	  request: Request,
65	  { params }: { params: Promise<{ id: string }> }
66	) {
67	  const { id } = await params;
68	  try {
69	    const txnCount = await prisma.transaction.count({
70	      where: { itemId: id },
71	    });
72	    if (txnCount > 0) {
73	      return NextResponse.json(
74	        { error: "该物料存在出入库记录，不能删除" },
75	        { status: 400 }
76	      );
77	    }
78	    await prisma.item.delete({ where: { id } });
79	    return NextResponse.json({ success: true });
80	  } catch {
81	    return NextResponse.json({ error: "物料不存在" }, { status: 404 });
82	  }
83	}
