3	import { useEffect, useState, useCallback } from "react";
4	import Link from "next/link";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Card, CardContent } from "@/components/ui/card";
8	import { Badge } from "@/components/ui/badge";
9	import {
10	  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
11	} from "@/components/ui/table";
12	import {
13	  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
14	} from "@/components/ui/select";
15	import { ItemFormDialog } from "@/components/item-form-dialog";
16	
17	interface Category {
18	  id: string;
19	  name: string;
20	  parentId: string | null;
21	  _count?: { items: number };
22	}
23	
24	interface Item {
25	  id: string;
26	  code: string;
27	  name: string;
28	  description: string | null;
29	  sn: string | null;
30	  model: string | null;
31	  manufacturer: string | null;
32	  categoryId: string;
33	  unit: string;
34	  quantity: number;
35	  safetyStock: number;
36	  position: string | null;
37	  supplier: string | null;
38	  price: number | null;
39	  warrantyStart: string | null;
40	  warrantyEnd: string | null;
41	  nandType: string | null;
42	  compatibleProducts: string | null;
43	  category: Category;
44	}
