46	export default function ItemsPage() {
47	  const [items, setItems] = useState<Item[]>([]);
48	  const [categories, setCategories] = useState<Category[]>([]);
49	  const [q, setQ] = useState("");
50	  const [categoryId, setCategoryId] = useState("");
51	  const [dialogOpen, setDialogOpen] = useState(false);
52	  const [editing, setEditing] = useState<Item | null>(null);
53	
54	  const loadItems = useCallback(async () => {
55	    const params = new URLSearchParams();
56	    if (q) params.set("q", q);
57	    if (categoryId) params.set("categoryId", categoryId);
58	    const res = await fetch(`/api/items?${params}`);
59	    setItems(await res.json());
60	  }, [q, categoryId]);
61	
62	  const loadCategories = async () => {
63	    const res = await fetch("/api/categories");
64	    setCategories(await res.json());
65	  };
66	
67	  useEffect(() => { loadCategories(); }, []);
68	  useEffect(() => { loadItems(); }, [loadItems]);
69	
70	  const handleSearch = () => loadItems();
71	
72	  const categoryName = (cat: Category) =>
73	    cat.parentId ? `  └ ${cat.name}` : cat.name;
74	
75	  const categoriesFlat = categories.flatMap((c) => {
76	    const result = [c];
77	    const children = categories.filter((x) => x.parentId === c.id);
78	    result.push(...children);
79	    return result;
80	  });
81	
82	  return (
83	    <div className="p-6 max-w-7xl mx-auto">
84	      <div className="flex items-center justify-between mb-6">
85	        <h1 className="text-2xl font-bold">物料管理</h1>
86	        <Button onClick={() => { setEditing(null); setDialogOpen(true); }}>
87	          新增物料
88	        </Button>
89	      </div>
90	
91	      {/* 搜索和筛选 */}
92	      <div className="flex gap-3 mb-4">
93	        <Input
94	          placeholder="搜索名称/编号/型号/SN..."
95	          value={q}
96	          onChange={(e) => setQ(e.target.value)}
97	          onKeyDown={(e) => e.key === "Enter" && handleSearch()}
98	          className="max-w-sm"
99	        />
100	        <Select
101	          value={categoryId || "null"}
102	          onValueChange={(v) => setCategoryId(!v || v === "null" ? "" : v)}
103	        >
104	          <SelectTrigger className="w-48">
105	            <SelectValue placeholder="全部分类" />
106	          </SelectTrigger>
107	          <SelectContent>
108	            <SelectItem value="null">全部分类</SelectItem>
109	            {categoriesFlat.map((c) => (
110	              <SelectItem key={c.id} value={c.id}>
111	                {categoryName(c)}
112	              </SelectItem>
113	            ))}
114	          </SelectContent>
115	        </Select>
116	        <Button variant="secondary" onClick={handleSearch}>搜索</Button>
117	      </div>
118	
119	      {/* 桌面端表格 */}
120	      <div className="hidden md:block">
121	        <Table>
122	          <TableHeader>
123	            <TableRow>
124	              <TableHead>编号</TableHead>
125	              <TableHead>名称</TableHead>
126	              <TableHead>型号</TableHead>
127	              <TableHead>分类</TableHead>
128	              <TableHead>库存</TableHead>
129	              <TableHead>位置</TableHead>
130	              <TableHead>操作</TableHead>
131	            </TableRow>
132	          </TableHeader>
133	          <TableBody>
134	            {items.map((item) => (
135	              <TableRow key={item.id}>
136	                <TableCell className="font-mono text-sm">{item.code}</TableCell>
137	                <TableCell>
138	                  <Link href={`/items/${item.id}`} className="hover:underline">
139	                    {item.name}
140	                  </Link>
141	                </TableCell>
142	                <TableCell className="text-muted-foreground">
143	                  {item.model ?? "-"}
144	                </TableCell>
145	                <TableCell>
146	                  <Badge variant="outline">{item.category.name}</Badge>
147	                </TableCell>
148	                <TableCell>
149	                  <span
150	                    className={
151	                      item.quantity <= item.safetyStock && item.safetyStock > 0
152	                        ? "text-red-600 font-semibold"
153	                        : ""
154	                    }
155	                  >
156	                    {item.quantity} {item.unit}
157	                  </span>
158	                </TableCell>
159	                <TableCell className="text-muted-foreground">
160	                  {item.position ?? "-"}
161	                </TableCell>
162	                <TableCell>
163	                  <Button
164	                    variant="ghost" size="sm"
165	                    onClick={() => { setEditing(item); setDialogOpen(true); }}
166	                  >
167	                    编辑
168	                  </Button>
169	                </TableCell>
170	              </TableRow>
171	            ))}
172	          </TableBody>
173	        </Table>
174	      </div>
175	
176	      {/* 手机端卡片 */}
177	      <div className="md:hidden space-y-3">
178	        {items.map((item) => (
179	          <Card key={item.id}>
180	            <CardContent className="p-4">
181	              <div className="flex justify-between items-start">
182	                <div>
183	                  <Link href={`/items/${item.id}`} className="font-semibold hover:underline">
184	                    {item.name}
185	                  </Link>
186	                  <p className="text-sm text-muted-foreground">{item.code}</p>
187	                </div>
188	                <Badge
189	                  variant={item.quantity <= item.safetyStock && item.safetyStock > 0 ? "destructive" : "secondary"}
190	                >
191	                  {item.quantity} {item.unit}
192	                </Badge>
193	              </div>
194	              <div className="flex gap-2 mt-2 text-sm text-muted-foreground">
195	                <span>{item.category.name}</span>
196	                {item.position && <span>| {item.position}</span>}
197	              </div>
198	            </CardContent>
199	          </Card>
200	        ))}
201	      </div>
202	
203	      {items.length === 0 && (
204	        <p className="text-center text-muted-foreground py-12">暂无物料</p>
205	      )}
206	
207	      <ItemFormDialog
208	        open={dialogOpen}
209	        onOpenChange={setDialogOpen}
210	        item={editing}
211	        categories={categoriesFlat}
212	        onSaved={loadItems}
213	      />
214	    </div>
215	  );
216	}
