40	  const removeRow = (i: number) => {
41	    if (rows.length === 1) return;
42	    setRows(rows.filter((_, idx) => idx !== i));
43	  };
44	
45	  const updateRow = (i: number, field: keyof Row, value: string | number) => {
46	    setRows((prev) => {
47	      const next = [...prev];
48	      next[i] = { ...next[i], [field]: value };
49	      return next;
50	    });
51	  };
52	
53	  const handleSubmit = async () => {
