55	    if (valid.length === 0) return;
56	
57	    setSubmitting(true);
58	    const body = {
59	      type,
60	      items: valid.map((r) => ({
61	        itemId: r.itemId,
62	        quantity: r.quantity,
63	        reason: r.reason,
64	        relatedPerson: r.relatedPerson,
65	        note: r.note,
66	      })),
67	    };
