4	export async function PUT(
5	  request: Request,
6	  { params }: { params: Promise<{ id: string }> }
7	) {
8	  const { id } = await params;
9	  const data = await request.json();
10	
11	  if (!data.name || typeof data.name !== "string" || data.name.trim().length === 0) {
12	    return NextResponse.json({ error: "分类名称不能为空" }, { status: 400 });
13	  }
14	
15	  try {
16	    const category = await prisma.category.update({
17	      where: { id },
18	      data: {
19	        name: data.name.trim(),
20	        parentId: data.parentId || null,
21	        description: data.description || null,
22	      },
23	    });
24	    return NextResponse.json(category);
25	  } catch (error) {
26	    return NextResponse.json({ error: "分类不存在" }, { status: 404 });
27	  }
28	}
29	
30	export async function DELETE(
31	  request: Request,
32	  { params }: { params: Promise<{ id: string }> }
33	) {
34	  const { id } = await params;
35	
36	  // Check for child categories
37	  const childCount = await prisma.category.count({ where: { parentId: id } });
38	  if (childCount > 0) {
39	    return NextResponse.json(
40	      { error: "该分类下存在子分类，不能删除" },
41	      { status: 400 }
42	    );
43	  }
44	
45	  // Check for items in this category
46	  const itemCount = await prisma.item.count({ where: { categoryId: id } });
47	  if (itemCount > 0) {
48	    return NextResponse.json(
49	      { error: "该分类下存在物料，不能删除" },
50	      { status: 400 }
51	    );
52	  }
53	
54	  try {
55	    await prisma.category.delete({ where: { id } });
56	    return NextResponse.json({ success: true });
57	  } catch (error) {
58	    return NextResponse.json({ error: "分类不存在" }, { status: 404 });
59	  }
60	}
